package co.aplomo.web;
import co.aplomo.servicio.*;import co.aplomo.dao.*;import co.aplomo.modelo.*;import co.aplomo.soporte.*;import co.aplomo.db.Sql;
import org.junit.jupiter.api.*;import java.util.*;import java.io.*;import java.net.*;import java.net.http.*;import javax.imageio.ImageIO;
import static org.junit.jupiter.api.Assertions.*;
/** RF-023a/b, RF-002, RNF-004/007: formulario, CSRF, origen protegido y reserva de Reevaluación. */
class HttpSugerenciasTest extends HttpPrueba {
    Evaluaciones evs;Sugerencias servicio;int visita,evaluacion,id;
    @BeforeEach void contexto()throws Exception{ReglasSugerenciasPrueba.cargar(con);evs=new Evaluaciones(tx,reloj,new Fotos(carpetaFotos),new BitacoraDao());servicio=evs.sugerencias();var salon=crearSalon();int puesto=new Empresas(tx).guardar(cuenta(admin),new Puesto(0,salon.id(),null,null,1,"Ensamble","MESA","Centro",null,true)).id();var r=new Reservas(tx,reloj);int reserva=r.guardar(cuenta(admin),0,solicitud(salon));r.aceptar(cuenta(admin),reserva);visita=new Visitas(tx,reloj).iniciar(cuenta(admin),reserva);var b=new ByteArrayOutputStream();ImageIO.write(new java.awt.image.BufferedImage(12,12,1),"png",b);evaluacion=evs.guardar(cuenta(admin),visita,new Evaluaciones.Datos(puesto,"Trabajo","MAS_INADECUADA","Postura mantenida",120,true,true,true,false,false,true,"",true,false),List.of(new Fotos.Entrada(b.toByteArray(),"PERFIL","Prueba")),List.of(new Analisis.Solicitud(0,CasosRulaPrueba.todos().get(9).entrada())));id=servicio.listar(cuenta(admin),evaluacion).get(0).sugerencia().id();entrar(admin);}
    @Test void crearEditarYOrigenProtegidoConHtmlEscapado()throws Exception{var f=new HashMap<>(Map.of("csrf",csrf(get("/sugerencias/"+id+"/editar")),"titulo","<script>inocuo</script>","descripcion","Texto\nconservado","tipo","OTRA","prioridad","BAJA","fecha","2026-11-25","origen","ADMINISTRADOR","id_regla","999999"));assertEquals(303,post("/sugerencias/"+id,f).statusCode());var s=servicio.consultar(cuenta(admin),id).sugerencia();assertEquals("SISTEMA",s.origen());assertNotEquals(999999,s.regla());var r=get("/sugerencias/"+id);assertTrue(r.body().contains("&lt;script&gt;inocuo&lt;/script&gt;"));assertFalse(r.body().contains("<script>inocuo"));assertTrue(r.body().contains("25 nov 2026"));assertFalse(r.body().contains("/fotos/"));f.put("csrf",csrf(get("/sugerencias/nueva?evaluacion="+evaluacion)));assertEquals(303,post("/sugerencias?evaluacion="+evaluacion,f).statusCode());}
    @Test void erroresConservanFormularioYUltimaSugerenciaNoSeQuita()throws Exception{String token=csrf(get("/sugerencias/"+id+"/editar"));var r=post("/sugerencias/"+id,Map.of("csrf",token,"titulo","Mi mejora","descripcion","No perder este texto","tipo","POSTURA","prioridad","ALTA","fecha","0001-01-01"));assertEquals(400,r.statusCode());assertTrue(r.body().contains("No perder este texto"));assertTrue(r.body().contains("value=\"ALTA\" selected"));assertTrue(r.body().contains("0001-01-01"));assertFalse(r.body().contains("SQLException"));for(var f:servicio.listar(cuenta(admin),evaluacion))if(f.sugerencia().id()!=id)servicio.quitar(cuenta(admin),f.sugerencia().id());assertEquals(400,post("/sugerencias/"+id+"/quitar",Map.of("csrf",token)).statusCode());assertTrue(servicio.consultar(cuenta(admin),id).sugerencia().activo());}
    @Test void estadoCsrfYMetodosProtegidos()throws Exception{assertEquals(405,get("/sugerencias/"+id+"/quitar").statusCode());assertEquals(405,get("/sugerencias/"+id+"/estado").statusCode());assertEquals(403,post("/sugerencias/"+id+"/estado",Map.of("csrf","malo","estado","HECHA")).statusCode());String t=csrf(get("/sugerencias/"+id));assertEquals(303,post("/sugerencias/"+id+"/estado",Map.of("csrf",t,"estado","EN_PROCESO")).statusCode());assertEquals("EN_PROCESO",servicio.consultar(cuenta(admin),id).sugerencia().estado());}
    @Test void hechasOfreceReservaPreparadaSinCrearlaAutomaticamente()throws Exception{int antes=Sql.uno(con,"SELECT COUNT(*) FROM reserva",r->r.getInt(1));for(var f:servicio.listar(cuenta(admin),evaluacion))servicio.estado(cuenta(admin),f.sugerencia().id(),"HECHA");var r=get("/sugerencias/"+id);assertTrue(r.body().contains("Registrar reevaluación"));var e=servicio.contexto(cuenta(admin),evaluacion);var nueva=get("/reservas/nueva?empresa="+e.empresa()+"&sede="+e.sede()+"&salon="+e.salon()+"&categoria=REEVALUACION");assertEquals(200,nueva.statusCode());assertTrue(nueva.body().contains("value=\"REEVALUACION\" selected"));assertEquals(antes,Sql.<Integer>uno(con,"SELECT COUNT(*) FROM reserva",r1->r1.getInt(1)));}
    @Test void usuarioConsultaSinFotosYNoModificaPorDireccionDirecta()throws Exception{dao.contrasena(con,usuario,cuenta(usuario).hash(),false);cliente=HttpClient.newBuilder().cookieHandler(new CookieManager(null,CookiePolicy.ACCEPT_ALL)).build();entrar(usuario);assertEquals(403,get("/sugerencias/"+id).statusCode());new Visitas(tx,reloj).finalizar(cuenta(admin),visita,"");var r=get("/sugerencias/"+id);assertEquals(200,r.statusCode());assertFalse(r.body().contains("Editar sugerencia"));assertFalse(r.body().contains("Quitar sugerencia"));assertFalse(r.body().contains("Guardar estado"));assertFalse(r.body().contains("/fotos/"));assertEquals(403,get("/sugerencias/"+id+"/editar").statusCode());assertEquals(403,get("/sugerencias/nueva?evaluacion="+evaluacion).statusCode());String t=csrf(get("/"));assertEquals(403,post("/sugerencias/"+id+"/estado",Map.of("csrf",t,"estado","HECHA")).statusCode());assertEquals(403,post("/sugerencias/"+id+"/quitar",Map.of("csrf",t)).statusCode());}
    @Test void otraEmpresaYQuitadasNoSonVisiblesParaUsuario()throws Exception{new Visitas(tx,reloj).finalizar(cuenta(admin),visita,"");servicio.quitar(cuenta(admin),id);dao.contrasena(con,usuario,cuenta(usuario).hash(),false);cliente=HttpClient.newBuilder().cookieHandler(new CookieManager(null,CookiePolicy.ACCEPT_ALL)).build();entrar(usuario);assertEquals(403,get("/sugerencias/"+id).statusCode());int otra=Sql.insertar(con,"INSERT INTO empresa (id_administrador,nombre,nit) VALUES (?,?,?)",admin,"Otra empresa",UUID.randomUUID().toString().substring(0,20));int u=insertar("USUARIO",otra,cuenta(admin).hash(),false);cliente=HttpClient.newBuilder().cookieHandler(new CookieManager(null,CookiePolicy.ACCEPT_ALL)).build();entrar(u);assertEquals(403,get("/sugerencias?evaluacion="+evaluacion).statusCode());}
    @Test void sinReglasAplicablesGuardaYExplicaQueFaltaUna()throws Exception{var f=new EvaluacionDao().fotos(con,evaluacion).get(0);int nueva=evs.guardar(cuenta(admin),visita,new Evaluaciones.Datos(servicio.contexto(cuenta(admin),evaluacion).puesto(),"Solo carga","MAS_INADECUADA","Trabajo",60,false,false,false,false,false,false,"",true,false),List.of(new Fotos.Entrada(new Fotos(carpetaFotos).leer(f.nombre()),"PERFIL","Prueba")),List.of(new Analisis.Solicitud(0,CasosRulaPrueba.todos().get(8).entrada())));assertTrue(servicio.listar(cuenta(admin),nueva).isEmpty());var r=get("/evaluaciones/"+nueva);assertEquals(200,r.statusCode());assertTrue(r.body().contains("El análisis está guardado."));assertTrue(r.body().contains("Escribe" )||r.body().contains("escribe una"));}
    @Test void vistaPreviaIncluyeReglaDentroDelCalculoSinInsertar()throws Exception{int antes=servicio.listar(cuenta(admin),evaluacion).size();var campos=CasosRulaPrueba.campos(CasosRulaPrueba.todos().get(9).entrada());campos.put("csrf",csrf(get("/")));campos.put("visita",""+visita);campos.put("pies","si");var r=post("/evaluaciones/calcular",campos);assertEquals(200,r.statusCode());assertTrue(r.body().contains("reposapiés o bajar la silla"));assertTrue(r.body().contains("Sugerencias · aparte del puntaje"));assertEquals(antes,servicio.listar(cuenta(admin),evaluacion).size());assertTrue(get("/static/js/sugerencias.js").body().contains("Tus campos"));assertTrue(get("/pendientes").body().contains("7 · Rojo · Nivel 4"));assertTrue(get("/visitas/"+visita).body().contains("7 · Rojo · Nivel 4"));}
}
